"""
Incident Monitor for VPSO
Auto-detects incidents and reports to SKP API
"""
import requests
import json
import time
from datetime import datetime

API_BASE = "http://localhost:8000"
API_KEY = "hermes-orchestrator-key-2026"  # Master key for incidents

def get_api_status():
    """Get overall API health status"""
    try:
        resp = requests.get(f"{API_BASE}/health", timeout=5)
        if resp.status_code == 200:
            return resp.json()
    except Exception as e:
        return {"error": str(e)}
    return None

def get_agents_status():
    """Get all agents status"""
    try:
        headers = {"X-API-Key": API_KEY}
        resp = requests.get(f"{API_BASE}/agents", headers=headers, timeout=5)
        if resp.status_code == 200:
            return resp.json()
    except Exception as e:
        print(f"Error getting agents: {e}")
    return []

def report_incident(title, description, severity, agent_id=None, tags=None):
    """Report incident to SKP via /knowledge endpoint"""
    if tags is None:
        tags = ["#incident", "#alert"]

    knowledge_data = {
        "title": f"[INCIDENT] {title}",
        "content": f"""
## Incident Report
**Time**: {datetime.now().isoformat()}
**Severity**: {severity}
**Agent**: {agent_id or 'SYSTEM'}
**Description**: {description}

---
*Auto-generated by incident-monitor.py*
        """.strip(),
        "tags": tags,
        "source_agent_id": "incident-monitor"
    }

    try:
        headers = {"X-API-Key": API_KEY}
        resp = requests.post(
            f"{API_BASE}/knowledge",
            headers=headers,
            json=knowledge_data,
            timeout=5
        )
        if resp.status_code in [200, 201]:
            print(f"✅ Incident reported: {title}")
            return True
        else:
            print(f"❌ Failed to report incident: {resp.status_code} - {resp.text}")
    except Exception as e:
        print(f"❌ Error reporting incident: {e}")
    return False

def check_agent_incidents(agents):
    """Check for agent-related incidents"""
    incidents = []

    for agent in agents:
        status = agent.get("status", "unknown")
        agent_id = agent.get("agent_id", "unknown")

        # Check for offline agents
        if status == "offline":
            incidents.append({
                "title": f"Agent {agent_id} is OFFLINE",
                "description": f"Agent {agent_id} has been detected as offline during routine check.",
                "severity": "HIGH",
                "agent_id": agent_id,
                "tags": ["#incident", "#alert", "#agent-offline"]
            })

        # Check for agents with error status
        elif status == "error":
            incidents.append({
                "title": f"Agent {agent_id} in ERROR state",
                "description": f"Agent {agent_id} is in error state.",
                "severity": "CRITICAL",
                "agent_id": agent_id,
                "tags": ["#incident", "#alert", "#agent-error"]
            })

    return incidents

def check_system_incidents(health_data):
    """Check for system-wide incidents"""
    incidents = []

    # Check Redis
    redis_status = health_data.get("checks", {}).get("redis", {}).get("status")
    if redis_status != "healthy":
        incidents.append({
            "title": "Redis is UNHEALTHY",
            "description": f"Redis status: {redis_status}. Message: {health_data.get('checks', {}).get('redis', {}).get('message', 'N/A')}",
            "severity": "CRITICAL",
            "tags": ["#incident", "#alert", "#redis"]
        })

    # Check Database
    db_status = health_data.get("checks", {}).get("database", {}).get("status")
    if db_status != "healthy":
        incidents.append({
            "title": "Database is UNHEALTHY",
            "description": f"Database status: {db_status}.",
            "severity": "CRITICAL",
            "tags": ["#incident", "#alert", "#database"]
        })

    # Check queue
    queue_data = health_data.get("checks", {}).get("queue", {})
    pending = queue_data.get("details", {}).get("pending_tasks", 0)
    if pending > 50:  # Threshold
        incidents.append({
            "title": f"High pending tasks: {pending}",
            "description": f"Queue has {pending} pending tasks. This may indicate processing issues.",
            "severity": "MEDIUM",
            "tags": ["#incident", "#alert", "#queue"]
        })

    return incidents

def main():
    print(f"🔍 Incident Monitor - {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
    print("=" * 50)

    # Get health status
    health = get_api_status()
    if not health:
        print("❌ Cannot connect to API. Reporting API downtime...")
        report_incident(
            title="SKP API is UNREACHABLE",
            description="The SKP API at localhost:8000 is not responding.",
            severity="CRITICAL",
            tags=["#incident", "#alert", "#api-down"]
        )
        return

    print(f"✅ API Status: {health.get('status')}")

    # Get agents
    agents = get_agents_status()
    print(f"✅ Agents found: {len(agents)}")

    # Check for incidents
    all_incidents = []

    # System incidents
    system_incidents = check_system_incidents(health)
    all_incidents.extend(system_incidents)

    # Agent incidents
    agent_incidents = check_agent_incidents(agents)
    all_incidents.extend(agent_incidents)

    # Report all incidents
    if all_incidents:
        print(f"\n🚨 Found {len(all_incidents)} incident(s):")
        for inc in all_incidents:
            print(f"  - [{inc['severity']}] {inc['title']}")
            report_incident(**inc)
    else:
        print("\n✅ No incidents detected. System healthy.")

    print("=" * 50)
    print("Done.")

if __name__ == "__main__":
    main()
